         }
         drawingManager.handleClick(e);
    }, [tool, drawingManager]);

    return (
        <>
            <gridHelper args={[100, 100]} />
            <ambientLight intensity={0.5} />
            <directionalLight position={[10, 20, 10]} intensity={0.8} castShadow />

            <CameraHandler view={currentView} onFinished={() => setCurrentView(null)} />

            <OrbitControls 
                makeDefault 
