            {drawingManager.selectionBox.start && drawingManager.selectionBox.current && (
                <Html fullscreen style={{ pointerEvents: 'none' }}>
                     <SelectionBox start={drawingManager.selectionBox.start} end={drawingManager.selectionBox.current} />
